"""Shared helpers for emitting task TOML with a computed answer key."""

from __future__ import annotations

from pathlib import Path
from typing import Any

TASKS_DIR = Path(__file__).resolve().parent.parent

BANNER = (
    "# Generated by tasks/generators/build.py — do not edit by hand.\n"
    "# The answer key below is computed from the same data that builds the\n"
    "# prompt, so the two cannot drift apart.\n"
)


def _toml_value(value: Any) -> str:
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int | float):
        return repr(value)
    if isinstance(value, list):
        return "[" + ", ".join(_toml_value(item) for item in value) + "]"
    return '"' + str(value).replace("\\", "\\\\").replace('"', '\\"') + '"'


def _block(text: str) -> str:
    """A TOML multi-line string that survives quotes and backslashes."""
    return "'''\n" + text.strip("\n") + "\n'''"


def write_task(
    category: str,
    task_id: str,
    *,
    difficulty: str,
    prompt: str,
    criteria: str,
    checks: list[dict[str, Any]],
) -> Path:
    lines = [
        BANNER,
        f"category = {_toml_value(category)}",
        f"difficulty = {_toml_value(difficulty)}",
        "",
        f"prompt = {_block(prompt)}",
        "",
        f"criteria = {_block(criteria)}",
        "",
    ]
    for check in checks:
        lines.append("[[checks]]")
        for key, value in check.items():
            lines.append(f"{key} = {_toml_value(value)}")
        lines.append("")

    path = TASKS_DIR / category / f"{task_id}.toml"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text("\n".join(lines))
    return path


def json_checks(expected: dict[str, Any], weight: float = 1.0) -> list[dict[str, Any]]:
    """One check per answer field, so a partly-right answer scores partly.

    A single all-or-nothing check on the whole document would put a model that
    got five of six aggregations right level with one that got none, which is
    the opposite of what a discriminating task should do.
    """
    checks: list[dict[str, Any]] = [{"type": "json_valid", "weight": weight}]
    checks += [
        {"type": "json_path", "path": path, "equals": value, "weight": weight}
        for path, value in expected.items()
    ]
    return checks
